return {["scripts/actions/abilities/fire_shot.lua"]={["Path"]="scripts/actions/abilities/fire_shot.lua",["SHA256"]="00e7a56a089af48ac701a4c9652e95079697806ae501c5b88e8123c02e221c74",["Text"]="-----------------------------------\n-- Ability: Fire Shot\n-- Consumes a Fire Card to enhance fire-based debuffs. Deals fire-based magic damage\n-- Burn effect: Enhanced DoT and INT-\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.checkQuickDraw(player, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.corsair.useElementalShot(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/flabra.lua"]={["Path"]="scripts/actions/abilities/flabra.lua",["SHA256"]="11698d584bed4b61b63b5a651675b6780aeb464687a6717aa669830f3f8b20a1",["Text"]="-----------------------------------\n-- Ability: Flabra\n-- Increases resistance against earth and deals wind damage.\n-- Obtained: Rune Fencer Level 5\n-- Recast Time: 0:05\n-- Duration: 5:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.rune_fencer.useRuneEnchantment(player, target, ability, xi.effect.FLABRA)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/flashy_shot.lua"]={["Path"]="scripts/actions/abilities/flashy_shot.lua",["SHA256"]="2945831be7687e64e0cf958f21cff27977a83549689e2aa8bbc3003237641f0c",["Text"]="-----------------------------------\n-- Ability: Flashy Shot\n-- Next attack will generate more enmity and ignore level difference penalties.\n-- Obtained: Ranger Level 75\n-- Recast Time: 10:00\n-- Duration: 1:00\n-- Target: Self Only\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.ranger.checkFlashyShot(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.ranger.useFlashyShot(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/flee.lua"]={["Path"]="scripts/actions/abilities/flee.lua",["SHA256"]="ba1ecf747ffcfeb0e278be62856b4506e6ebb97b4b6700bd78999bb3f892d839",["Text"]="-----------------------------------\n-- Ability: Flee\n-- Increases movement speed.\n-- Obtained: Thief Level 25\n-- Recast Time: 5:00\n-- Duration: 0:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.thief.useFlee(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/fly_high.lua"]={["Path"]="scripts/actions/abilities/fly_high.lua",["SHA256"]="228438bb2f7b7ff03e462c5e34984a52abc36d64718ab73421e3a7f52cbf4e99",["Text"]="-----------------------------------\n-- Ability: Fly High\n-- Description: Decreases the recast time of jumps.\n-- Obtained: DRG Level 96\n-- Recast Time: 01:00:00\n-- Duration: 00:00:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    ability:setRecast(math.max(0, ability:getRecast() - player:getMod(xi.mod.ONE_HOUR_RECAST) * 60))\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.dragoon.useFlyHigh(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/focalization.lua"]={["Path"]="scripts/actions/abilities/focalization.lua",["SHA256"]="b3229c7873af51c5e486ec4a37f7b4a654374a0430b3e55c6f5f11c3104d08c6",["Text"]="-----------------------------------\n-- Ability: Focalization\n-- Increases the accuracy of your next black magic spell.\n-- Obtained: Scholar Level 75\n-- Recast Time: Stratagem Charge\n-- Duration: 1 black magic spell or 60 seconds, whichever occurs first\n--\n-- Level   |Charges |Recharge Time per Charge\n-- -----   -------- ---------------\n-- 10      |1       |4:00 minutes\n-- 30      |2       |2:00 minutes\n-- 50      |3       |1:20 minutes\n-- 70      |4       |1:00 minute\n-- 90      |5       |48 seconds\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.FOCALIZATION) then\n        return xi.msg.basic.EFFECT_ALREADY_ACTIVE, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:addStatusEffect(xi.effect.FOCALIZATION, { power = player:getMerit(xi.merit.FOCALIZATION), duration = 60, origin = player })\n\n    return xi.effect.FOCALIZATION\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/focus.lua"]={["Path"]="scripts/actions/abilities/focus.lua",["SHA256"]="729ceb6a2beba2e2b87a1ff766160e97265dbaedd7d849dea11b41ef58925c92",["Text"]="-----------------------------------\n-- Ability: Focus\n-- Enhances user's accuracy.\n-- Obtained: Monk Level 25\n-- Recast Time: 5:00\n-- Duration: 2:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.monk.useFocus(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/fold.lua"]={["Path"]="scripts/actions/abilities/fold.lua",["SHA256"]="8af87fc4d311980a480d0206ebc6242ff372df9b8001e69af37deb7026cde191",["Text"]="-----------------------------------\n-- Ability: Fold\n-- Erases one roll or bust xi.effect. Targets self-cast effect with the longest remaining duration.\n-- Obtained: Corsair Level 75\n-- Recast Time: 00:05:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.checkFold(player)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.corsair.useFold(player, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/footwork.lua"]={["Path"]="scripts/actions/abilities/footwork.lua",["SHA256"]="d6acb1569990bee01c3d52882a691a2e4fa318a3ffcdfc3d1144d6fb47b31a55",["Text"]="-----------------------------------\n-- Ability: Footwork\n-- Makes kicks your primary mode of attack.\n-- Obtained: Monk Level 65\n-- Recast Time: 5:00\n-- Duration: 1:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.monk.useFootwork(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/formless_strikes.lua"]={["Path"]="scripts/actions/abilities/formless_strikes.lua",["SHA256"]="a32a21a70355939e6982a1111f166e612a805a1ba9cddccbbd085ab9a6afb506",["Text"]="-----------------------------------\n-- Ability: Formless Strikes\n-- While in effect, melee attacks will not be considered physical damage. No effect on weapon skills.\n-- Obtainable: Monk Level 75\n-- Recast Time: 0:10:00\n-- Duration: 0:03:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.monk.useFormlessStrikes(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/full_circle.lua"]={["Path"]="scripts/actions/abilities/full_circle.lua",["SHA256"]="3325c84af5f70da87c34c7867c701cd9cdc4d8ca87d8a6f5ff7947ce25fc1185",["Text"]="-----------------------------------\n-- Ability: Full Circle\n-- Causes your luopan to vanish.\n-- Obtained: Geomancer Level 5\n-- Recast Time: 10 seconds\n-- Refunds some of the MP consumed by the Geocolure spell that created the luopan.\n-- Amount of MP restored varies depending on remaining Luopan HP.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.geomancer.geoOnAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    xi.job_utils.geomancer.fullCircle(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/futae.lua"]={["Path"]="scripts/actions/abilities/futae.lua",["SHA256"]="68d83a2f2398a1a6745ec31aa61407d00baaba68fbe2626850c7ffc3b6286e3a",["Text"]="-----------------------------------\n-- Ability: Futae\n-- Grants a bonus to your next elemental ninjutsu by expending two ninja tools.\n-- Obtained: Ninja Level 77\n-- Recast Time: 3:00\n-- Duration: 1:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.ninja.checkFutae(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.ninja.useFutae(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/gallants_roll.lua"]={["Path"]="scripts/actions/abilities/gallants_roll.lua",["SHA256"]="eb982513fa4131f94ce23ba05437af0254f0817500c895c3db2e60fe0e328326",["Text"]="-----------------------------------\n-- Ability: Gallant's Roll\n-- Enhances defense for party members within area of effect\n-- Optimal Job: Paladin\n-- Lucky Number: 3\n-- Unlucky Number: 7\n-- Level: 55\n-- Phantom Roll +1 Value: 2\n--\n-- Die Roll    |No PLD  |With PLD\n-- --------    -------  -----------\n-- 1           |4%      |15%\n-- 2           |5%      |16%\n-- 3           |19%     |30%\n-- 4           |7%      |18%\n-- 5           |8%      |19%\n-- 6           |10%     |21%\n-- 7           |3%      |14%\n-- 8           |11%     |22%\n-- 9           |13%     |24%\n-- 10          |15%     |26%\n-- 11          |23%     |34%\n-- Bust        |-11%    |-11%\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/gambit.lua"]={["Path"]="scripts/actions/abilities/gambit.lua",["SHA256"]="f4c74b72a81f6672208adbc7b7a62e3dffd69c4a6816ea1ad01b608622593042",["Text"]="-----------------------------------\n-- Ability: Gambit\n-- Expends all runes harbored to reduce an enemy's elemental defense. The types of elemental defense reduced depend on the runes you harbor.\n-- Obtained: Rune Fencer level 70\n-- Recast Time: 5:00\n-- Duration: 1:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.rune_fencer.checkHaveRunes(player)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.rune_fencer.useGambit(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/gauge.lua"]={["Path"]="scripts/actions/abilities/gauge.lua",["SHA256"]="6827464e6eae4f8877e23647a59f8f92a9b329a728517be4ed1dc21938d666f4",["Text"]="-----------------------------------\n-- Ability: Gauge\n-- Checks to see if an enemy can be charmed.\n-- Obtained: Beastmaster Level 10\n-- Recast Time: 0:30\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.beastmaster.checkGauge(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.beastmaster.useGauge(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/gelus.lua"]={["Path"]="scripts/actions/abilities/gelus.lua",["SHA256"]="aaaff1e265f02fb9dbe0ec6108c9219626941ebe55a7eb1313aefc487e494682",["Text"]="-----------------------------------\n-- Ability: Gelus\n-- Increases resistance against wind and deals ice damage.\n-- Obtained: Rune Fencer Level 5\n-- Recast Time: 0:05\n-- Duration: 5:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.rune_fencer.useRuneEnchantment(player, target, ability, xi.effect.GELUS)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/grand_pas.lua"]={["Path"]="scripts/actions/abilities/grand_pas.lua",["SHA256"]="afff75260da99555eed9f8c37b7685a22b05cc4d34a36cb901a3e0f89222c7e9",["Text"]="-----------------------------------\n-- Ability: Grand Pas\n-- Description: Allows flourishes to be performed without finishing moves.\n-- Obtained: DNC Level 96\n-- Recast Time: 01:00:00\n-- Duration: 00:00:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    ability:setRecast(math.max(0, ability:getRecast() - player:getMod(xi.mod.ONE_HOUR_RECAST) * 60))\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    target:addStatusEffect(xi.effect.GRAND_PAS, { power = 19, duration = 30, origin = player, tick = 1 })\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/hagakure.lua"]={["Path"]="scripts/actions/abilities/hagakure.lua",["SHA256"]="f087ccf5b3ae30e249485e8276440bdc49d6e405c3956e932fd77659cb5c657f",["Text"]="-----------------------------------\n-- Ability: Hagakure\n-- Grants \"Save TP\" effect and a TP bonus to your next weapon skill.\n-- Obtained: Samurai Level 95\n-- Recast Time: 3:00\n-- Duration: 1:00 or Next Weaponskill\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.samurai.useHagakure(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/hamanoha.lua"]={["Path"]="scripts/actions/abilities/hamanoha.lua",["SHA256"]="81028e9cc4b1d0890dd788e5f74e70458462c23bfd2fb7911796d8f18f22b6dd",["Text"]="-----------------------------------\n-- Ability: Hamanoha\n-- Description: Lowers accuracy, evasion, magic accuracy, magic evasion and TP gain for demons.\n-- Obtained: SAM Level 87\n-- Recast Time: 00:05:00\n-- Duration: 0:03:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.samurai.useHamanoha(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/hasso.lua"]={["Path"]="scripts/actions/abilities/hasso.lua",["SHA256"]="1f219d7265b7e08e0d53990302feef92cd675db7a85b02ca5457753f6ead031d",["Text"]="-----------------------------------\n-- Ability: Hasso\n-- Grants a bonus to attack speed, accuracy, and Strength when using two-handed weapons, but increases recast and casting times.\n-- Obtained: Samurai Level 25\n-- Recast Time: 1:00\n-- Duration: 5:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.samurai.checkHasso(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.samurai.useHasso(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/haste_samba.lua"]={["Path"]="scripts/actions/abilities/haste_samba.lua",["SHA256"]="8c837ea46dffc8d3577d9673ac78f23ad0c22f60a3dd0aa8fc1ca41565936f26",["Text"]="-----------------------------------\n-- Ability: Haste Samba\n-- Inflicts the next target you strike with Haste daze, increasing the attack speed of all those engaged in battle with it.\n-- Obtained: Dancer Level 45\n-- TP Cost: 35%\n-- Recast Time: 1:00\n-- Duration: 1:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.FAN_DANCE) then\n        return xi.msg.basic.UNABLE_TO_USE_JA2, 0\n    elseif player:getTP() < 350 then\n        return xi.msg.basic.NOT_ENOUGH_TP, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    -- Only remove TP if the player doesn't have Trance.\n    if not player:hasStatusEffect(xi.effect.TRANCE) then\n        player:delTP(350)\n    end\n\n    local duration = 120 + player:getMod(xi.mod.SAMBA_DURATION) + (player:getJobPointLevel(xi.jp.SAMBA_DURATION) * 2)\n    duration       = duration * (100 + player:getMod(xi.mod.SAMBA_PDURATION)) / 100\n    player:delStatusEffect(xi.effect.DRAIN_SAMBA)\n    player:delStatusEffect(xi.effect.ASPIR_SAMBA)\n    player:addStatusEffect(xi.effect.HASTE_SAMBA, { power = 500 + player:getMerit(xi.merit.HASTE_SAMBA_EFFECT), duration = duration, origin = player })\n\n    return xi.effect.HASTE_SAMBA\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/heady_artifice.lua"]={["Path"]="scripts/actions/abilities/heady_artifice.lua",["SHA256"]="18d6606d13eeaed87d68f84197dea51dc209129140a78a533f3125284ff2e688",["Text"]="-----------------------------------\n-- Ability: Heady Artifice\n-- Description: Allows automatons to perform a special ability that varies with the head used.\n-- Obtained: PUP Level 96\n-- Recast Time: 01:00:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.puppetmaster.onAbilityCheckHeadyArtiface(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.puppetmaster.onAbilityUseHeadyArtifice(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/healers_roll.lua"]={["Path"]="scripts/actions/abilities/healers_roll.lua",["SHA256"]="ca0c674ddf836d18f6c10e1bc5c9e9e5d3e7710cf1111780b86a62041fdbd097",["Text"]="-----------------------------------\n-- Ability: Healer's Roll\n-- Increases potency of \"Cure\" effect received for party members within area of effect\n-- Optimal Job: White Mage\n-- Lucky Number: 3\n-- Unlucky Number: 7\n-- Level: 20\n-- Phantom Roll +1 Value: 3\n--\n-- Die Roll    |No WHM  |With WHM\n-- --------    -------  -----------\n-- 1           |+3%     |+7%\n-- 2           |+4%     |+8%\n-- 3           |+12%    |+16%\n-- 4           |+5%     |+9%\n-- 5           |+6%     |+10%\n-- 6           |+7%     |+11%\n-- 7           |+1%     |+5%\n-- 8           |+8%     |+12%\n-- 9           |+9%     |+13%\n-- 10          |+10%    |+14%\n-- 11          |+16%    |+20%\n-- Bust        |-4%     |-4%\n--\n-- Note that this roll will increase potency of cures received, not the potency of the caster's spells\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/healing_waltz.lua"]={["Path"]="scripts/actions/abilities/healing_waltz.lua",["SHA256"]="803c50698d2e9366df919c8bbebf200587b8b91c145aa9f3537ecfadbfa9919f",["Text"]="-----------------------------------\n-- Ability: Healing Waltz\n-- Removes one detrimental status effect from target party member.\n-- Obtained: Dancer Level 35\n-- TP Required: 20%\n-- Recast Time: 00:15\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    local waltzCost = 200 - player:getMod(xi.mod.WALTZ_COST) * 10\n    if target:getHP() == 0 then\n        return xi.msg.basic.CANNOT_ON_THAT_TARG, 0\n    elseif player:hasStatusEffect(xi.effect.SABER_DANCE) then\n        return xi.msg.basic.UNABLE_TO_USE_JA2, 0\n    elseif player:hasStatusEffect(xi.effect.TRANCE) then\n        return 0, 0\n    elseif player:getTP() < waltzCost then\n        return xi.msg.basic.NOT_ENOUGH_TP, 0\n    else\n        --[[ Apply \"Waltz Ability Delay\" reduction\n            1 modifier = 1 second]]\n        local recastMod = player:getMod(xi.mod.WALTZ_DELAY)\n        if recastMod ~= 0 then\n            local newRecast = ability:getRecast() + recastMod\n            ability:setRecast(utils.clamp(newRecast, 0, newRecast))\n        end\n\n        -- Apply \"Fan Dance\" Waltz recast reduction\n        if player:hasStatusEffect(xi.effect.FAN_DANCE) then\n            local fanDanceMerits = target:getMerit(xi.merit.FAN_DANCE)\n            -- Every tier beyond the 1st is -5% recast time\n            if fanDanceMerits > 5 then\n                ability:setRecast(ability:getRecast() * ((fanDanceMerits - 5) / 100))\n            end\n        end\n\n        -- Inform core we want to cleanup Contradance if it's active after the ability is done\n        ability:setPostActionCleanupEffect(xi.effect.CONTRADANCE)\n\n        return 0, 0\n    end\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    local waltzCost = 200 - player:getMod(xi.mod.WALTZ_COST) * 10\n    -- Only remove TP if the player doesn't have Trance.\n    if not player:hasStatusEffect(xi.effect.TRANCE) then\n        player:delTP(waltzCost)\n    end\n\n    local effect = target:healingWaltz()\n\n    if effect == xi.effect.NONE then\n        ability:setMsg(xi.msg.basic.NO_EFFECT) -- no effect\n    else\n        ability:setMsg(xi.msg.basic.JA_REMOVE_EFFECT)\n    end\n\n    return effect\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/heel.lua"]={["Path"]="scripts/actions/abilities/heel.lua",["SHA256"]="b3eb70d203428da0cf7bbc3315abedf63ad9e08650b561195bd7ab1bf5025cf1",["Text"]="-----------------------------------\n-- Ability: Heel\n-- Commands the pet to cease attacking and return to you.\n-- Obtained: Beastmaster Level 10\n-- Recast Time: 5 seconds\n-- Duration: N/A\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.beastmaster.checkPetCommand(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.beastmaster.useHeel(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/hide.lua"]={["Path"]="scripts/actions/abilities/hide.lua",["SHA256"]="2ca1ac1258272fc5ed0593467f1370ecd0e87aed276ab8abb12c65dbe168fda4",["Text"]="-----------------------------------\n-- Ability: Hide\n-- User becomes invisible.\n-- Obtained: Thief Level 45\n-- Recast Time: 5:00\n-- Duration: Random\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.thief.useHide(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/high_jump.lua"]={["Path"]="scripts/actions/abilities/high_jump.lua",["SHA256"]="4b1b2dd62872b73fd67337cb775bb268ac658fe616223c76078721baa263c2f0",["Text"]="-----------------------------------\n-- Ability: High Jump\n-- Performs a high jumping attack on enemy.\n-- Obtained: Dragoon Level 35\n-- Recast Time: 2:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.dragoon.useHighJump(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/holy_circle.lua"]={["Path"]="scripts/actions/abilities/holy_circle.lua",["SHA256"]="7d1e16e73f460b0204cf732d6920ef8026a45089ed210c0ff41c861ccfca0e90",["Text"]="-----------------------------------\n-- Ability: Holy Circle\n-- Grants resistance, defense, and attack against Undead to party members within the area of effect.\n-- Obtained: Paladin Level 5\n-- Recast Time: 5:00 minutes\n-- Duration: 3:00 minutes\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.paladin.useHolyCircle(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/hundred_fists.lua"]={["Path"]="scripts/actions/abilities/hundred_fists.lua",["SHA256"]="20034f5a00e9e47ef0a505d3e29a64fffe2f21286150b7d74e679acbb3fa17fb",["Text"]="-----------------------------------\n-- Ability: Hundred Fists\n-- Speeds up attacks.\n-- Obtained: Monk Level 1\n-- Recast Time: 1:00:00\n-- Duration: 0:00:45\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.monk.checkHundredFists(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.monk.useHundredFists(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/hunters_roll.lua"]={["Path"]="scripts/actions/abilities/hunters_roll.lua",["SHA256"]="0a2a55eb9082c628c1b1ec58234cd56b2d32874c1386a3c4afbcc1e00262f901",["Text"]="-----------------------------------\n-- Ability: Hunter's Roll\n-- Enhances accuracy and ranged accuracy for party members within area of effect\n-- Optimal Job: Ranger\n-- Lucky Number: 4\n-- Unlucky Number: 8\n-- Level: 11\n-- Phantom Roll +1 Value: 5\n--\n-- Die Roll    |Without RNG |With RNG\n-- --------    ------------ -------\n-- 1           |+10         |+25\n-- 2           |+13         |+28\n-- 3           |+15         |+30\n-- 4           |+40         |+55\n-- 5           |+18         |+33\n-- 6           |+20         |+35\n-- 7           |+25         |+40\n-- 8           |+5          |+20\n-- 9           |+28         |+43\n-- 10          |+30         |+45\n-- 11          |+50         |+65\n-- Bust        |-15         |-15\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/ice_maneuver.lua"]={["Path"]="scripts/actions/abilities/ice_maneuver.lua",["SHA256"]="14c43451f6542989d1ce36cf380a45333261d50e71c63755debe3d89defd141b",["Text"]="-----------------------------------\n-- Ability: Ice Maneuver\n-- Enhances the effect of ice attachments. Must have animator equipped.\n-- Obtained: Puppetmaster level 1\n-- Recast Time: 10 seconds (shared with all maneuvers)\n-- Duration: 1 minute\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.automaton.onManeuverCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.automaton.onUseManeuver(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/ice_shot.lua"]={["Path"]="scripts/actions/abilities/ice_shot.lua",["SHA256"]="a630b143f73df29af3de8cb9bc82986f2e5b8aae5dd5f8b6a8bbbd4c7016f664",["Text"]="-----------------------------------\n-- Ability: Ice Shot\n-- Consumes an Ice Card to enhance ice-based debuffs. Deals ice-based magic damage\n-- Frost Effect: Enhanced DoT and AGI-\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.checkQuickDraw(player, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.corsair.useElementalShot(player, target, ability, action)\nend\n\nreturn abilityObject\n"}};
